/* Grille 2 lignes x 3 colonnes (CORRIGÉ) */
.responsive-buttons-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  /* ✅ Harmonisé à 3 colonnes */
  grid-template-rows: repeat(2, auto);
  gap: 1vw;
  width: 100%;
  box-sizing: border-box;
  padding: 1vw;
}
/* Suppression des styles QSR (btn-pink) */
/* Rangée horizontale pour les autres boutons */
.responsive-buttons-row {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 1vw;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  padding: 1vw;
