  /* overflow: hidden; <-- Supprimé */
}
.responsive-buttons-grid {
  grid-template-rows: repeat(2, 1fr);
}
.responsive-buttons-row {
  grid-template-rows: 1fr;
}
.responsive-buttons-grid .round-button-wrapper,
.responsive-buttons-row .round-button-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
}
/* Boutons parfaitement ronds et adaptatifs */
.responsive-buttons-grid .custom-round-button,
.responsive-buttons-row .custom-round-button {
  aspect-ratio: 1;
  width: 60%;
  max-width: 80px;
  min-width: 32px;
  height: auto;
  border-radius: 50%;
  font-size: 2vw;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.5vw;
  transition: width 0.2s, font-size 0.2s;
  box-sizing: border-box;
  overflow: hidden;
}
/* Labels adaptatifs */
.responsive-buttons-grid .button-label,
.responsive-buttons-row .button-label {
  font-size: 1vw;
  min-font-size: 10px;
  max-font-size: 16px;
  font-weight: 500;
  word-break: break-word;
  text-align: center;
  line-height: 1.1;
}
