  background-color: #111;
  color: #fff;
  border: none;
  border-radius: 24px;
  padding: 0.3vw 1vw;
  font-size: 1vw;
  font-weight: 500;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.15);
  cursor: pointer;
  transition: background 0.2s;
  outline: none;
  display: flex;
  align-items: center;
}
.user-guide-btn:hover {
  background-color: #222;
}
/* Responsive pour très petits écrans */
@media (max-width: 700px) {
  .responsive-buttons-grid,
  .responsive-buttons-row {
    gap: 0.5vw;
    padding: 0.5vw;
  }
  .responsive-buttons-grid .custom-round-button,
  .responsive-buttons-row .custom-round-button {
    width: 80%;
    max-width: 48px;
    font-size: 3vw;
  }
  .responsive-buttons-grid .button-label,
  .responsive-buttons-row .button-label {
