#widget-w_container_content{
  #widget-w_container_filter{
    z-index:40;
    transition: all ease 0.5s;
    top:0%;
    left:0%;
    height: 100%;
    width:20%;
    background:#eff1f4;
    box-shadow: 0 0 10px #ccc;
    transform:scale(1,1);
    transform-origin: top left;

  }
  .hide-filter{
    
    #widget-w_container_filter{
      transform:scale(0,1);
      width: 3%!important;
    }

    #widget-w_container_all_tables{
      width: 97%;
    }
  }

  .show-graph{
    
    #widget-w_container_all_tables{
      transform:scale(0,1);
      width: 0%!important;
    }

    #widget-w_container_graphs{
      width: 97%!important;
    }
  }

  .show-contour{
    
    #widget-w_container_all_tables{
      transform:scale(0,1);
      width: 0%!important;
    }

    #widget-w_container_contour{
      width: 97%!important;
    }
  }


}



