.custom-round-button {
    background-color: white;
    border-radius: 50%;
    width: 80px;
    height: 80px;
    border: none;
    font-size: 33px;
  transition: box-shadow 0.3s ease;

  }

  .round-button-wrapper {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin: 10px;
  }

  .button-label {
    font-size: 20px;
    margin-top: 5px;
    font-weight: bold;
  }

  /* Couleurs personnalisées pour chaque bouton */
  .btn-red .custom-round-button,
  .btn-red .button-label {
    color: #CC0000;
  }

  .btn-redfod .custom-round-button,
  .btn-redfod .button-label {
    color: #FF5349;
  }

  .btn-blue_era .custom-round-button,
  .btn-blue_era .button-label {
    color: #0F056B;
  }
  .btn-blue .custom-round-button,
  .btn-blue .button-label {
    color: #038A9D;
  }

  .btn-green .custom-round-button,
  .btn-green .button-label {
    color: green;
  }

  .btn-purple .custom-round-button,
  .btn-purple .button-label {
    color: purple;
  }

    .btn-red .custom-round-button:hover {
    box-shadow: 0 0 10px #BE0A6E;
  }

  .btn-blue .custom-round-button:hover {
    box-shadow: 0 0 10px #038A9D;
  }

  .btn-redfod .custom-round-button:hover {
    box-shadow: 0 0 10px #B00626;
  }

  .btn-green .custom-round-button:hover {
    box-shadow: 0 0 10px green;
  }

  .btn-purple .custom-round-button:hover {
    box-shadow: 0 0 10px purple;
  }

  .custom-round-button:hover {
    outline: none;
    background-color: white !important;
  }

  .round-button-wrapper {
    text-decoration: none;
  }

  .round-button-wrapper:hover {
    text-decoration: none;
  }


.btn-waterfall .custom-round-button,
.btn-waterfall .button-label {
    color: #00208b;
}


.btn-waterfall .custom-round-button:hover {
    box-shadow: 0 0 10px #00208b;
}

.btn-cyan .custom-round-button,
.btn-cyan .button-label {
    color: #2c97a4; /* Un cyan plus doux */
}

.btn-cyan .custom-round-button:hover {
    box-shadow: 0 0 10px #2c97a4;
}

